#!/usr/bin/env bash
# Extract only the owner-approved circular Job Ranger mark from the clean
# repository lockup. Source: docs/assets/branding/job-ranger-logo.png.
#
# IMPORTANT: the red-circled preview is an annotation, not the source art.
# This extraction is a crop only: no AI redraw, recoloring or resampling.
# Reviewed reference geometry: 2048x682, crop x=45..594, y=51..600.
#
# The native transparent square icon is 550x550. Platform variants are
# generated by the existing ImageMagick distribution-icon pipeline.
set -euo pipefail

cd "$(dirname "$0")/.."
src="docs/assets/branding/job-ranger-logo.png"
out="public/ICON.png"

if ! command -v identify >/dev/null || ! command -v convert >/dev/null; then
  echo "ImageMagick identify + convert required for exact logo extraction" >&2
  exit 1
fi

dims="$(identify -format '%wx%h' "$src")"
if [[ "$dims" != "2048x682" ]]; then
  echo "Unexpected source size: $dims (expected 2048x682). Do not guess crop coordinates." >&2
  exit 1
fi

# Tight transparent square: excludes the wordmark starting near x=600 and
# has modest padding around the full circular emblem at 16-512px.
convert "$src" -crop 550x550+45+51 +repage -strip "PNG32:$out"
actual="$(identify -format '%wx%h' "$out")"
[[ "$actual" = "550x550" ]] || { echo "Extracted icon size mismatch: $actual" >&2; exit 1; }

cp "$out" public/favicon.png
bash scripts/generate-distribution-icons.sh
echo "Job Ranger emblem extracted to $out; favicon, PWA and AppX icons regenerated."
echo "Inspect the output visually at 16, 32, 44, 192 and 512px before shipping."
